              className
            )}
          >
            {triggerLabel ? <span>{triggerLabel}</span> : null}
            {items}
          </div>
        </OpenInChatContext.Provider>
      </TooltipProvider>
    );
  }

  return (
    <OpenInChatContext.Provider value={contextValue}>
      <div {...props} className={cn("inline-flex", className)}>
        <DropdownMenu>
          <DropdownMenuTrigger
            render={
              trigger ?? (
                <Button
                  type="button"
                  variant="outline"
                  className={cn("gap-2", triggerClassName)}
                >
                  {triggerLabel}
                  <ChevronDown
                    className="size-4 opacity-70"
                    aria-hidden="true"
                  />
                </Button>
              )
            }
          />
          <DropdownMenuContent
            align={align}
            side={side}
            className={cn("w-56", contentClassName)}
          >
            {items}
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </OpenInChatContext.Provider>
  );
}

export function OpenInChatLink({
  label,
  prompt,
  className,
  baseUrl,
  paramName = "q",
  icon
}: OpenInChatLinkProps) {
  const { prompt: contextPrompt, layout } = useOpenInChat();

  const href = getPromptUrl(baseUrl, prompt ?? contextPrompt, paramName);

  const Icon = icon;

  if (layout === "horizontal") {
    return (
