          >
            {triggerLabel ? <span>{triggerLabel}</span> : null}
            {items}
          </div>
        </OpenInChatContext.Provider>
      </TooltipProvider>
    );
  }

  return (
    <OpenInChatContext.Provider value={contextValue}>
      <div {...props} className={cn("inline-flex", className)}>
        <DropdownMenu>
