                  {triggerLabel}
                  <ChevronDown
                    className="size-4 opacity-70"
                    aria-hidden="true"
                  />
                </Button>
              )
            }
          />
          <DropdownMenuContent
            align={align}
            side={side}
            className={cn("w-56", contentClassName)}
          >
            {items}
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </OpenInChatContext.Provider>
  );
