                className
              )}
            >
              <Icon className="size-4" aria-hidden="true" />
            </a>
          }
        />
        <TooltipContent sideOffset={6}>Open in {label}</TooltipContent>
      </Tooltip>
    );
  }

  return (
    <DropdownMenuItem
      className={cn("cursor-pointer", className)}
      render={
