      {...params}
    />
  );
}

export function OpenInPerplexity(params: OpenInChatProviderLinkProps) {
  const dat = aiLinksDataMap.Perplexity;

  return (
    <OpenInChatLink
      label="Perplexity"
      baseUrl={dat.baseUrl}
      icon={dat.icon}
      paramName={dat.paramName}
      {...params}
    />
  );
}

export function OpenInGrok(params: OpenInChatProviderLinkProps) {
