  return (
    <OpenInChatLink
      label="Perplexity"
      baseUrl={dat.baseUrl}
      icon={dat.icon}
      paramName={dat.paramName}
      {...params}
    />
  );
}

export function OpenInGrok(params: OpenInChatProviderLinkProps) {
  const dat = aiLinksDataMap.Grok;

  return (
    <OpenInChatLink
      label="Grok"
      baseUrl={dat.baseUrl}
      icon={dat.icon}
